function maker(val) {
  var obj1 = { val }; 
  function add(obj2){
     return obj1.val + obj2.val;
  }
  return { obj: obj1, add };
}

var { obj, add } = maker(100);
console.log(add({val: 100 }));
obj.val = -100;
console.log(add({val: 100 })); 
